/* 向野 · 统一深色旅行手帐界面；保留 app.js 的数据与事件。 */
(() => {
  const ratio = t => {
    if (!t) return {done:0,total:0,percent:0};
    const items=checklistItems(t),custom=t.customItems||[];
    const total=items.length+custom.length;
    const done=items.filter(x=>t.checked?.[x.id]).length+custom.filter(x=>t.checked?.[`custom:${x.id}`]).length;
    return {done,total,percent:total?Math.round(done/total*100):0};
  };
  const ring=(done,total,small=false,light=false)=>{
    const value=total?Math.round(done/total*100):0;
    return `<div class="ring ${small?'ring-sm':''} ${light?'ring-light':''}" style="--seg1:${value*.25}%;--seg2:${value*.5}%;--seg3:${value*.75}%;--seg4:${value}%" role="img" aria-label="准备事项已完成${done}项，共${total}项"><span><b>${done}/${total}</b><small>已准备</small></span></div>`;
  };
  const placeName=(t,key)=>escapeHtml(findPlace(t,key)?.name||key.split('|')[0]);
  const infoValue=(t,key)=>escapeHtml(t.info?.[key]||'待填写');

  renderTrips=function(){const all=trips();return `<section class="page-hero"><span class="page-overline">MY JOURNEYS</span><h1 class="page-title">路上的日子</h1><p class="sub">每段旅程，都有自己的节奏。</p></section><div class="overview-grid"><div class="overview-tile tile-pink"><small>已保存旅程</small><strong>${all.length}</strong></div><div class="overview-tile tile-yellow"><small>准备中的下一站</small><strong>${all.length?escapeHtml(all[0].destination):'还没有'}</strong></div></div><div class="section-heading"><h2 class="section-title">旅行档案</h2></div>${all.length?all.map(t=>{const r=ratio(t);return `<article class="journey-card"><div class="journey-top"><div><span class="status-chip">${t.travelStyle==='stay'?'一地慢住':'沿途探索'}</span><h2>${escapeHtml(t.destination)}</h2><p>${escapeHtml(t.origin)}出发 · ${prettyDate(t.start)}—${prettyDate(t.end)}</p></div>${ring(r.done,r.total,true,true)}</div><div class="actions"><button class="primary" data-action="open-trip" data-id="${t.id}">打开行程</button><button class="secondary" data-action="edit-trip" data-id="${t.id}">编辑计划</button></div></article>`}).join(''):'<div class="empty">还没有旅程。先选一个地方，把第一段路存下来。</div>'}<button class="secondary full" data-action="new-trip">＋ 开始一段新旅程</button>`};

  renderPlan=function(){const v=planDefaults(),d=state.planDestination||getDestination(state.editTrip)||matchingCatalog(v.destination),style=state.editTrip?.travelStyle||state.planTravelStyle||'explore',base=state.editTrip?.stayBase||d?.center||'';return `<section class="page-hero"><span class="page-overline">MAKE A JOURNEY</span><h1 class="page-title">${state.editTrip?'重写这段旅程':'先写下想去的地方'}</h1><p class="sub">你的时间、预算与步调，我们一起排成路线。</p></section><form id="planForm"><div class="section-heading"><h2 class="section-title">01 · 去哪里</h2></div><span class="small muted">旅行范围</span><div class="segmented"><button type="button" data-action="set-region" data-region="国内" class="${v.region==='国内'?'selected':''}">中国境内</button><button type="button" data-action="set-region" data-region="出境" class="${v.region==='出境'?'selected':''}">出境旅行</button></div><label class="field"><span>从哪里出发</span><input name="origin" value="${escapeHtml(v.origin)}" required></label><label class="field"><span>想到哪里去</span><input name="destination" value="${escapeHtml(v.destination)}" placeholder="国家、城市或景点" required></label><div class="section-heading"><h2 class="section-title">02 · 什么时候</h2></div><div class="field-row"><label class="field"><span>出发</span><input type="date" name="start" value="${v.start}" required></label><label class="field"><span>返回</span><input type="date" name="end" value="${v.end}" required></label></div><div class="field-row"><label class="field"><span>人数</span><input type="number" name="people" min="1" max="20" value="${v.people}" required></label><label class="field"><span>总预算 ¥</span><input type="number" name="budget" min="0" step="100" value="${v.budget}" required></label></div><div class="section-heading"><h2 class="section-title">03 · 怎么待</h2></div><div class="style-card"><span class="small muted">旅行方式</span><div class="segmented"><button type="button" data-action="travel-style" data-style="explore" class="${style==='explore'?'selected':''}">沿途探索</button><button type="button" data-action="travel-style" data-style="stay" class="${style==='stay'?'selected':''}">一地慢住</button></div><p class="small muted">慢住每隔一天只安排一个地点，其余时间留白。</p><label class="field"><span>慢住落脚地</span><input name="stayBase" value="${escapeHtml(base)}" placeholder="例如：开罗、京都、巴黎"></label></div><label class="field"><span>每天想走多满</span><select name="pace"><option value="slow">少走一点</option><option value="balanced">经典景点与休息兼顾</option><option value="full">尽量多看一些</option></select></label><button class="primary full" type="submit">${state.editTrip?'保存并重新规划':'生成我的行程'} ↗</button><p id="planError" class="error" role="alert"></p></form><p class="section-note">费用仅用于初步规划；天气、门票、签证及交通请在出发前再次核实。</p>`};

  renderTrip=function(){const t=trip();if(!t)return renderTrips();const r=ratio(t),e=estimated(t),d=getDestination(t);return `<button class="text-button" data-action="all-trips">← 所有旅程</button><div class="trip-heading"><div><span class="page-overline">${t.travelStyle==='stay'?'SLOW STAY':'JOURNEY NOTES'}</span><h1 class="page-title">${escapeHtml(t.destination)}</h1><p class="sub">${prettyDate(t.start)}—${prettyDate(t.end)} · ${duration(t)}天 · ${t.people}人</p></div>${ring(r.done,r.total,true)}</div><div class="overview-grid"><div class="overview-tile tile-pink"><small>旅行预算</small><strong>¥${Number(t.budget).toLocaleString()}</strong></div><div class="overview-tile tile-blue"><small>粗略估算</small><strong>¥${e.total.toLocaleString()}</strong></div></div><div class="trip-tools"><button class="secondary" data-action="edit-trip" data-id="${t.id}">编辑基本信息</button><button class="secondary" data-action="open-destination">探索景点</button><button class="secondary" data-action="share-trip">分享文字行程</button></div><div id="weatherPanel" class="notice">天气只显示可查询的预报日期。正在核对…</div><div class="section-heading"><h2 class="section-title">每天怎么走</h2><span class="small muted">可以逐日调整</span></div><div class="timeline">${t.days.map((day,i)=>{const w=state.weatherFor===t.id&&state.weather?.[day.date];return `<article class="timeline-card"><span class="page-overline">DAY ${String(i+1).padStart(2,'0')} · ${prettyDate(day.date)}</span><h3>${i===0?'抵达，先熟悉这里':i===t.days.length-1?'收拾心情，准备返程':day.places.length?'今天去看看':'留给自己的一天'}</h3><p>${w?`${weatherLabel(w.code)} ${w.low}–${w.high}°C · `:''}${t.travelStyle==='stay'&&day.places.length===0?'不安排景点，慢慢待着。':day.places.length?`${day.places.length}处地点`:'这天尚未安排地点。'}</p><ul class="day-list">${day.places.map(key=>`<li><span><b>${placeName(t,key)}</b><br><small>${escapeHtml(findPlace(t,key)?.city||'')} · ${escapeHtml(findPlace(t,key)?.time||'约2小时')}</small></span><button data-action="remove-place" data-day="${i}" data-place="${escapeHtml(key)}" aria-label="移除${placeName(t,key)}">移除</button></li>`).join('')}</ul><button class="text-button" data-action="choose-place" data-day="${i}">＋ 添加地点</button></article>`}).join('')}</div><div class="section-heading"><h2 class="section-title">旅行资料夹</h2></div><p class="section-note">参考开源旅行页的信息结构：把交通、住宿、票务和用车集中在行程里。这里只保存你自己填的文字，不会自动订票。</p><div class="info-grid"><div class="info-field"><small>往返交通</small><strong>${infoValue(t,'transport')}</strong></div><div class="info-field"><small>住宿</small><strong>${infoValue(t,'hotel')}</strong></div><div class="info-field"><small>门票 / 预约</small><strong>${infoValue(t,'tickets')}</strong></div><div class="info-field"><small>当地交通 / 租车</small><strong>${infoValue(t,'rental')}</strong></div></div><form class="info-edit" id="tripInfoForm"><strong>把已确认的信息记下来</strong><p class="section-note">本机浏览器保存。请不要填写护照号、订单验证码或完整住址。</p><label class="field"><span>往返交通</span><input name="transport" value="${escapeHtml(t.info?.transport||'')}" placeholder="例如：火车或航班备注"></label><label class="field"><span>住宿</span><input name="hotel" value="${escapeHtml(t.info?.hotel||'')}" placeholder="例如：住在哪个区域"></label><label class="field"><span>门票 / 预约</span><input name="tickets" value="${escapeHtml(t.info?.tickets||'')}" placeholder="例如：故宫已预约"></label><label class="field"><span>当地交通 / 租车</span><input name="rental" value="${escapeHtml(t.info?.rental||'')}" placeholder="例如：地铁、包车或租车"></label><button class="primary full" type="submit">保存旅行资料</button></form><div class="section-heading"><h2 class="section-title">费用拆分</h2></div><div class="budget-grid"><div class="card"><span class="small muted">往返交通</span><strong>¥${e.flight}</strong></div><div class="card"><span class="small muted">住与吃</span><strong>¥${e.stay+e.food}</strong></div></div><p class="section-note">市内交通 ¥${e.local} · 门票 ¥${e.tickets}。按${t.people}人估算；不是实时价格。${e.total>t.budget?' 当前估算已超过预算。':''}</p><div class="actions"><button class="primary" data-action="checklist">去看出发清单</button></div>${d?.type==='country'&&d.places.some(p=>p.city!==d.center)?'<p class="notice">此行程可能跨城，城际交通需要单独确认。</p>':''}`};

  renderChecklist=function(){const t=trip();if(!t)return `<section class="page-hero"><span class="page-overline">READY TO GO</span><h1 class="page-title">出发前，慢慢准备</h1></section><div class="empty">先建立一段旅行，清单会根据国内或出境自动展开。</div><button class="primary full" data-action="new-trip">开始规划</button>`;const items=checklistItems(t),custom=t.customItems||[],r=ratio(t);const docs=items.filter(x=>['visa','entry','insurance'].includes(x.id)),booking=items.filter(x=>['transport','hotel','money','mobile'].includes(x.id)),packing=items.filter(x=>!docs.includes(x)&&!booking.includes(x));const rows=arr=>arr.map(x=>`<label class="check-row"><input type="checkbox" data-check="${escapeHtml(x.id)}" ${t.checked?.[x.id]?'checked':''}><span>${escapeHtml(x.label)}</span></label>`).join('');return `<section class="page-hero"><span class="page-overline">READY TO GO</span><h1 class="page-title">出发清单</h1><p class="sub">${escapeHtml(t.destination)} · ${prettyDate(t.start)}出发</p></section><div class="checklist-hero"><div><strong>每完成一件，<br>离出发近一点。</strong><p>已完成 ${r.done} / ${r.total} 件 · 只保存在本机</p></div>${ring(r.done,r.total)}</div>${docs.length?`<section class="check-section"><h2>证件与保障</h2>${rows(docs)}</section>`:''}<section class="check-section"><h2>预订与联络</h2>${rows(booking)}</section><section class="check-section"><h2>随身准备</h2>${rows(packing)}</section><section class="check-section"><h2>我自己的提醒</h2>${custom.map(x=>`<label class="check-row"><input type="checkbox" data-check="custom:${escapeHtml(x.id)}" ${t.checked?.[`custom:${x.id}`]?'checked':''}><span>${escapeHtml(x.label)}</span><button class="text-button" type="button" data-action="remove-custom" data-id="${escapeHtml(x.id)}">删除</button></label>`).join('')||'<p class="section-note">还没有自己添加的事项。</p>'}<form id="customItemForm" class="search-form"><input name="item" aria-label="新增准备事项" placeholder="加一件要准备的事"><button type="submit" aria-label="添加事项">＋</button></form></section>${t.region==='出境'?`<p class="notice">${escapeHtml(getDestination(t)?.visa||'签证和入境政策会变化，请以目的地官方要求为准。')}</p>`:''}`};

  renderProfile=function(){const all=trips(),t=trip(),r=ratio(t);return `<section class="profile-top"><span class="page-overline">A TRAVEL JOURNAL</span><h1>我的向野</h1><p class="sub">把想去的地方，变成可以慢慢走的路。</p></section><div class="profile-card"><div><span class="small muted">我的旅行档案</span><strong>${all.length} 段旅程</strong><p>${t?`下一站 ${escapeHtml(t.destination)} · ${prettyDate(t.start)}`:'还没有下一站，地球正等你转一转。'}</p></div>${ring(r.done,r.total)}</div><div class="overview-grid"><div class="overview-tile tile-lilac"><small>旅行方式</small><strong>${t?.travelStyle==='stay'?'慢住':'探索'}</strong></div><div class="overview-tile tile-yellow"><small>清单进度</small><strong>${r.percent}%</strong></div></div><div class="section-heading"><h2 class="section-title">最近的路</h2><button class="text-button" data-action="all-trips">看全部 ↗</button></div>${all.slice(0,3).map(x=>`<button class="trip-button" data-action="open-trip" data-id="${x.id}"><strong>${escapeHtml(x.destination)}</strong><small>${prettyDate(x.start)}—${prettyDate(x.end)} · ${duration(x)}天</small></button>`).join('')||'<div class="empty">还没有旅行记录。</div>'}<button class="primary full" data-action="new-trip">规划新旅程</button><hr class="dark-divider"><h2 class="section-title">关于向野</h2><p class="section-note">行程、勾选清单和旅行资料保存在当前浏览器。公开网址不会自动把这些内容同步给别人；换设备也不会自动出现。天气来自 Open-Meteo，景点信息可能来自公开百科，预算并非实时价格。</p>`};

  function expenseSection(t){const rows=t.expenses||[],total=rows.reduce((sum,x)=>sum+Number(x.amount||0),0);return `<div class="section-heading"><h2 class="section-title">旅途花费</h2><span class="small muted">自己记下的实际支出</span></div><div class="overview-grid"><div class="overview-tile tile-yellow"><small>已记录</small><strong>¥${total.toLocaleString()}</strong></div><div class="overview-tile tile-lilac"><small>平均每人</small><strong>¥${Math.round(total/(t.people||1)).toLocaleString()}</strong></div></div><form class="info-edit" id="expenseForm"><strong>记一笔</strong><div class="field-row"><label class="field"><span>金额 ¥</span><input name="amount" type="number" min="0.01" step="0.01" required></label><label class="field"><span>类别</span><select name="category"><option>交通</option><option>住宿</option><option>餐饮</option><option>门票</option><option>其他</option></select></label></div><label class="field"><span>备注</span><input name="note" maxlength="80" placeholder="例如：今天的午餐"></label><button class="secondary full" type="submit">＋ 保存这笔花费</button></form>${rows.length?`<div class="expense-list">${rows.slice().reverse().map(x=>`<div class="expense-row"><span><b>${escapeHtml(x.category)}</b><small>${escapeHtml(x.note||'未写备注')}</small></span><strong>¥${Number(x.amount).toLocaleString()}</strong><button data-action="remove-expense" data-id="${escapeHtml(x.id)}" aria-label="删除${escapeHtml(x.category)}花费">移除</button></div>`).join('')}</div>`:'<p class="section-note">还没有记录实际花费。预算估算与这份记录分开保存。</p>'}`}
  const tripBeforeLedger=renderTrip;
  renderTrip=function(){const html=tripBeforeLedger(),t=trip();if(!t)return html;return html.replace('<div class="actions"><button class="primary" data-action="checklist">',`${expenseSection(t)}<div class="actions"><button class="primary" data-action="checklist">`)};

  document.addEventListener('submit',event=>{if(event.target.id!=='tripInfoForm')return;event.preventDefault();const t=trip();if(!t)return;const data=new FormData(event.target);t.info={};for(const key of ['transport','hotel','tickets','rental'])t.info[key]=String(data.get(key)||'').trim().slice(0,160);saveTrip(t);render();notify('旅行资料已保存在当前浏览器。')});
  document.addEventListener('submit',event=>{if(event.target.id!=='expenseForm')return;event.preventDefault();const t=trip();if(!t)return;const data=new FormData(event.target),amount=Number(data.get('amount'));if(!Number.isFinite(amount)||amount<=0)return;t.expenses=t.expenses||[];t.expenses.push({id:uid(),amount:Math.round(amount*100)/100,category:String(data.get('category')||'其他'),note:String(data.get('note')||'').trim().slice(0,80)});saveTrip(t);render();notify('花费已记下。')});
  document.addEventListener('click',event=>{const b=event.target.closest('[data-action="remove-expense"]');if(!b)return;const t=trip();if(!t)return;t.expenses=(t.expenses||[]).filter(x=>x.id!==b.dataset.id);saveTrip(t);render();notify('这笔花费已移除。')});
  render();
})();
